SELECT CASE WHEN cost >= 83 THEN 'high' WHEN cost >= 22 THEN 'mid' ELSE 'low' END cost_bucket, ROUND(AVG(cost), 2) avg_cost, COUNT(CASE WHEN carrier = 'Kerry' THEN 1 END) kerry_count FROM shipments WHERE shipped_date >= '2024-10-30' AND carrier = 'DHL' AND delivered_date <= '2025-10-11' GROUP BY CASE WHEN cost >= 83 THEN 'high' WHEN cost >= 22 THEN 'mid' ELSE 'low' END ORDER BY kerry_count DESC, avg_cost DESC;
